import { writeFileSync } from "node:fs";
import { join } from "node:path";
import { bundleWorkflowCode } from "@temporalio/worker";

const root = join(import.meta.dir, "..");
const outputPath = join(root, "src/loop/temporal-workflow-bundle.generated.ts");
const workflowsPath = join(root, "src/loop/temporal-workflow.ts");
const bundle = await bundleWorkflowCode({ workflowsPath });
const encoded = Buffer.from(bundle.code, "utf8").toString("base64");
const chunks = encoded.match(/.{1,96}/g) ?? [];
const source = [
  "// Generated by scripts/build-temporal-workflow-bundle.ts. Do not edit.",
  "export const temporalWorkflowBundleBase64 = [",
  ...chunks.map((chunk) => `  ${JSON.stringify(chunk)},`),
  '].join("");',
  "",
].join("\n");

writeFileSync(outputPath, source, { encoding: "utf8", mode: 0o644 });
